mapper.select:
SELECT failure_id, question, targets, intent_types, entity_ids, lexical_keywords, expanded_queries, failure_type, failure_stage, retryable, eval_candidate, qdrant_hit_count, vector_chunk_count, lexical_chunk_count, merged_count, ranked_count, intent_filtered_count, judge_candidate_count, judged_count, final_ground_count, result_msg, public_message, diagnostic_message, review_status, promoted_eval_case_id, created_at FROM law_ai_search_failure_logs WHERE 1 = 1
AND eval_candidate = 1
AND review_status = #{reviewStatus}
ORDER BY created_at DESC, failure_id DESC LIMIT #{limit}

mapper.update:
UPDATE law_ai_search_failure_logs
SET review_status = 'PROMOTED',
    promoted_eval_case_id = #{caseId}
WHERE failure_id = #{failureId}
